// Basic usage with integers
std::atomic<int> shared_val(10);
int expected = 10;
int desired = 20;

bool success = shared_val.compare_exchange_strong(
    expected, desired);
// If success, shared_val is 20.
// If fail, expected is updated to the actual value.

// Usage with memory orders
std::atomic<void*> ptr(nullptr);
void* old_ptr = nullptr;
void* new_ptr = new int(5);

ptr.compare_exchange_strong(
    old_ptr, new_ptr,
    std::memory_order_acq_rel,
    std::memory_order_acquire);
delete new_ptr; // Cleanup
